import React from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom'; // 1. Додали імпорт
import App from './App';
import './App.css'; // Твої стилі

const root = createRoot(document.getElementById('root'));
root.render(
  // 2. Обгорнули App у BrowserRouter
  <BrowserRouter>
    <App />
  </BrowserRouter>
);
